"""記録の要旨と原文の引用を、LLM に渡す形に組み立てる（classify.py・refute.py で共用）。"""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
F = {f['id']: f for f in json.load(open(os.path.join(ROOT, 'publish/findings.json'), encoding='utf-8'))}
CIT = {r['rec']: r for r in json.load(open(os.path.join(ROOT, 'publish/citations.json'), encoding='utf-8'))['records']} if os.path.exists(os.path.join(ROOT, 'publish/citations.json')) else {}
# 判定に要る原文で、記録・引かれ方の引用に入っていないもの（2026-11-21：「比較対照群」が誰かを渡していなかったため判定が割れた）
EXTRA = {'NK-K1': ['「特2-1-4表 新受刑者数・認知症スクリーニング検査実施者・認知症の診断（平成30年〜令和3年）：平成30年 総数 18,272 60歳以上 3,294 検査実施者 893 医師による診察 131 認知症診断者 35／令和元年 17,464 3,296 908 206 50／2年 16,620 3,160 930 195 54／3年 16,152 3,284 973 183 55（注 法務省調査による）」（再犯防止推進白書 令和4年版 zentai_001389118.pdf 38頁）',
                   '「平成30年度から大規模な刑事施設８庁、令和元年度から女性刑事施設２庁を追加した合計10庁において、入所時年齢が60歳以上の受刑者を対象に認知症スクリーニング検査等を実施してきたところ、令和５年度からは、全国の刑事施設において、入所時年齢65歳以上の受刑者等を対象に認知症スクリーニング検査等を実施し、認知症等の早期把握に努めている。令和６年は、2,086人に認知症スクリーニング検査等を実施し、そのうち医師による診察を実施した者の中で132人が認知症の診断を受けた。」（再犯防止推進白書 令和7年版 zentai_001451882.pdf 64頁）',
                   '「刑事施設（市原青年矯正センターを除く。）においては、…入所受刑者のうち、刑執行開始時の年齢が65歳以上の者等に対して、認知症スクリーニング検査を実施し、認知症が疑われると判定された者には医師による診察を実施する取組を行っている。令和６年においては、2,086人に対して検査を実施し、そのうち、医師による診察を受けた者が284人、認知症と診断された者が132人であった（法務省矯正局の資料による。）。」（犯罪白書 令和7年版 r07_001455836.pdf 242〜243頁）'],
         'KP-C1': ['「指導を受講することが必要とされた者 1,980 名。うち，受講群は 1,444 名，比較対照群は 324 名。なお，両群の同質性確保のため，同指導を受講していないが，比較対照群としては不適当な者 212 名を除外している。」（法務省矯正局 分析結果について 001317461.pdf 1頁）']}
def src(rid):
    f = F[rid]
    qs = '\n'.join(f'  - 「{q["文"]}」（{q["ファイル"]} {q["箇所"]}）' for q in f.get('原文の引用', []))
    out = f'■ 記録 {rid}（資料：{f["統計"]}）\n要旨：{f["要旨"]}\n資料の原文：\n{qs}'
    if rid in CIT:   # 引かれ方で「元の資料」としている資料（記録の原文と別のことがある。2026-11-21：これを渡さず、答弁が正しく引いた資料を見落とした）
        c = CIT[rid]; cq = '\n'.join(f'  - 「{q["text"]}」（{q["label"]} {q["where"]}）' for q in c['src_quotes'])
        out += f'\n引かれ方の元の資料：{c["src"]}\nこの資料が言っていること：{c["says"]}\nこの資料の原文：\n{cq}'
    for t in EXTRA.get(rid, []): out += f'\n補足の原文：{t}'
    return out
def block(rids): return '\n'.join(src(r) for r in rids)
